import{_ as t,o as e,c as a,Q as d}from"./chunks/framework.48927342.js";const b=JSON.parse('{"title":"Making an Appointment with Dr Farrugia","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/dialogues/06-jodie-doctor-appointment.md","filePath":"en/more/maltese/practice/dialogues/06-jodie-doctor-appointment.md"}'),i={name:"en/more/maltese/practice/dialogues/06-jodie-doctor-appointment.md"},n=d('<h1 id="making-an-appointment-with-dr-farrugia" tabindex="-1">Making an Appointment with Dr Farrugia <a class="header-anchor" href="#making-an-appointment-with-dr-farrugia" aria-label="Permalink to &quot;Making an Appointment with Dr Farrugia&quot;">​</a></h1><p><strong>Scenario:</strong> Jodie calls the clinic to book an appointment with Dr Farrugia. They agree on Thursday at seven in the evening. (Speaker labels are inferred from the dialogue context, as the source is a listening exercise.)</p><h2 id="complete-dialogue" tabindex="-1">Complete Dialogue <a class="header-anchor" href="#complete-dialogue" aria-label="Permalink to &quot;Complete Dialogue&quot;">​</a></h2><p><strong>Jodie (Patient):</strong> Nista&#39; nagħmel appuntament għall-ġimgħa d-dieħla mat-tabib Farrugia?</p><p><strong>Receptionist:</strong> Il-ġimgħa d-dieħla għandi vojt l-Erbgħa u l-Ħamis.</p><p><strong>Jodie (Patient):</strong> L-Erbgħa ma nistax, imma l-Ħamis iva. Fi x&#39;hin?</p><p><strong>Receptionist:</strong> Filgħodu?</p><p><strong>Receptionist:</strong> Jew filgħaxija?</p><p><strong>Jodie (Patient):</strong> Filgħaxija aħjar, wara x-xogħol.</p><p><strong>Receptionist:</strong> Fis-6, fis-6:30, jew fis-7pm?</p><p><strong>Jodie (Patient):</strong> Fis-sebgħa tajjeb, grazzi!</p><p><strong>Receptionist:</strong> Ibbukkajt il-Ħamis fis-sebgħa ta&#39; filgħaxija.</p><p><strong>Receptionist:</strong> Nikkonferma, saħħa.</p><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><h3 id="_1-jodie-patient" tabindex="-1">1. Jodie (Patient) <a class="header-anchor" href="#_1-jodie-patient" aria-label="Permalink to &quot;1. Jodie (Patient)&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; nagħmel appuntament għall-ġimgħa d-dieħla mat-tabib Farrugia?</p><p><strong>Translation:</strong> Can I make an appointment for next week with Dr Farrugia?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>I can</td><td>First-person singular</td></tr><tr><td>nagħmel</td><td>I make; I arrange</td><td>First-person singular present</td></tr><tr><td>appuntament</td><td>appointment</td><td>Masculine loanword</td></tr><tr><td>għall-ġimgħa</td><td>for the week</td><td>Contracted <code>għal</code> + <code>il-ġimgħa</code></td></tr><tr><td>d-dieħla</td><td>coming; next</td><td><code>id-dieħla</code>, feminine singular of <code>dieħel</code> with the definite article</td></tr><tr><td>mat-tabib</td><td>with the doctor</td><td>Contracted <code>ma&#39;</code> + <code>it-tabib</code></td></tr><tr><td>Farrugia</td><td>Farrugia</td><td>The doctor&#39;s surname</td></tr></tbody></table><h3 id="_2-receptionist" tabindex="-1">2. Receptionist <a class="header-anchor" href="#_2-receptionist" aria-label="Permalink to &quot;2. Receptionist&quot;">​</a></h3><p><strong>Malti:</strong> Il-ġimgħa d-dieħla għandi vojt l-Erbgħa u l-Ħamis.</p><p><strong>Translation:</strong> Next week I am free on Wednesday and Thursday.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Il-ġimgħa</td><td>the week</td><td>Feminine noun with the definite article</td></tr><tr><td>d-dieħla</td><td>coming; next</td><td>Modifies <code>il-ġimgħa</code></td></tr><tr><td>għandi</td><td>I have</td><td>First-person singular form of <code>għand</code></td></tr><tr><td>vojt</td><td>free; vacant</td><td>Noun/adjective</td></tr><tr><td>l-Erbgħa</td><td>Wednesday</td><td>Day name with the definite article</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>l-Ħamis</td><td>Thursday</td><td>Day name with the definite article</td></tr></tbody></table><h3 id="_3-jodie-patient" tabindex="-1">3. Jodie (Patient) <a class="header-anchor" href="#_3-jodie-patient" aria-label="Permalink to &quot;3. Jodie (Patient)&quot;">​</a></h3><p><strong>Malti:</strong> L-Erbgħa ma nistax, imma l-Ħamis iva. Fi x&#39;hin?</p><p><strong>Translation:</strong> Wednesday I can&#39;t, but Thursday yes. At what time?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>L-Erbgħa</td><td>Wednesday</td><td>With the definite article</td></tr><tr><td>ma nistax</td><td>I cannot</td><td><code>ma</code> + <code>nista&#39;</code> + <code>x</code> forms the negative</td></tr><tr><td>imma</td><td>but</td><td>Contrasting conjunction</td></tr><tr><td>l-Ħamis</td><td>Thursday</td><td>With the definite article</td></tr><tr><td>iva</td><td>yes</td><td>Affirmative response</td></tr><tr><td>Fi</td><td>at; in</td><td>Variant of the preposition <code>f&#39;</code></td></tr><tr><td>x&#39;hin</td><td>what time</td><td><code>x&#39;</code> (what) + <code>hin</code> (time)</td></tr></tbody></table><h3 id="_4-receptionist" tabindex="-1">4. Receptionist <a class="header-anchor" href="#_4-receptionist" aria-label="Permalink to &quot;4. Receptionist&quot;">​</a></h3><p><strong>Malti:</strong> Filgħodu?</p><p><strong>Translation:</strong> In the morning?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Filgħodu</td><td>in the morning</td><td>Contracted <code>f&#39;</code> + <code>il-għodu</code>; printed <code>flgħodu</code> in the source, standard spelling <code>filgħodu</code></td></tr></tbody></table><h3 id="_5-receptionist" tabindex="-1">5. Receptionist <a class="header-anchor" href="#_5-receptionist" aria-label="Permalink to &quot;5. Receptionist&quot;">​</a></h3><p><strong>Malti:</strong> Jew filgħaxija?</p><p><strong>Translation:</strong> Or in the evening?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jew</td><td>or</td><td>Conjunction</td></tr><tr><td>filgħaxija</td><td>in the evening</td><td>Contracted <code>f&#39;</code> + <code>il-għaxija</code></td></tr></tbody></table><h3 id="_6-jodie-patient" tabindex="-1">6. Jodie (Patient) <a class="header-anchor" href="#_6-jodie-patient" aria-label="Permalink to &quot;6. Jodie (Patient)&quot;">​</a></h3><p><strong>Malti:</strong> Filgħaxija aħjar, wara x-xogħol.</p><p><strong>Translation:</strong> The evening is better, after work.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Filgħaxija</td><td>in the evening</td><td>Time expression</td></tr><tr><td>aħjar</td><td>better</td><td>Comparative of <code>tajjeb</code></td></tr><tr><td>wara</td><td>after</td><td>Preposition</td></tr><tr><td>x-xogħol</td><td>the work</td><td>Masculine noun with the definite article</td></tr></tbody></table><h3 id="_7-receptionist" tabindex="-1">7. Receptionist <a class="header-anchor" href="#_7-receptionist" aria-label="Permalink to &quot;7. Receptionist&quot;">​</a></h3><p><strong>Malti:</strong> Fis-6, fis-6:30, jew fis-7pm?</p><p><strong>Translation:</strong> At 6, at 6:30, or at 7 pm?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Fis-6</td><td>at 6</td><td>Contracted <code>f&#39;</code> + <code>is-</code> (numeral form)</td></tr><tr><td>jew</td><td>or</td><td>Conjunction</td></tr><tr><td>fis-7pm</td><td>at 7 pm</td><td><code>pm</code> indicates the evening</td></tr></tbody></table><h3 id="_8-jodie-patient" tabindex="-1">8. Jodie (Patient) <a class="header-anchor" href="#_8-jodie-patient" aria-label="Permalink to &quot;8. Jodie (Patient)&quot;">​</a></h3><p><strong>Malti:</strong> Fis-sebgħa tajjeb, grazzi!</p><p><strong>Translation:</strong> Seven is fine, thank you!</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Fis-sebgħa</td><td>at seven</td><td>Contracted <code>f&#39;</code> + <code>is-sebgħa</code></td></tr><tr><td>tajjeb</td><td>fine; good</td><td>Adjective</td></tr><tr><td>grazzi</td><td>thank you</td><td>Polite expression</td></tr></tbody></table><h3 id="_9-receptionist" tabindex="-1">9. Receptionist <a class="header-anchor" href="#_9-receptionist" aria-label="Permalink to &quot;9. Receptionist&quot;">​</a></h3><p><strong>Malti:</strong> Ibbukkajt il-Ħamis fis-sebgħa ta&#39; filgħaxija.</p><p><strong>Translation:</strong> I have booked Thursday at seven in the evening.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Ibbukkajt</td><td>I booked</td><td>Loanword <code>book</code>, first-person singular past</td></tr><tr><td>il-Ħamis</td><td>Thursday</td><td>With the definite article</td></tr><tr><td>fis-sebgħa</td><td>at seven</td><td>Time expression</td></tr><tr><td>ta&#39; filgħaxija</td><td>in the evening</td><td><code>ta&#39;</code> + <code>filgħaxija</code></td></tr></tbody></table><h3 id="_10-receptionist" tabindex="-1">10. Receptionist <a class="header-anchor" href="#_10-receptionist" aria-label="Permalink to &quot;10. Receptionist&quot;">​</a></h3><p><strong>Malti:</strong> Nikkonferma, saħħa.</p><p><strong>Translation:</strong> I confirm, bye.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nikkonferma</td><td>I confirm</td><td>Loanword <code>confirm</code></td></tr><tr><td>saħħa</td><td>bye; take care</td><td>Literally &quot;health&quot;; common farewell</td></tr></tbody></table>',54),o=[n];function r(s,h,l,c,g,p){return e(),a("div",null,o)}const u=t(i,[["render",r]]);export{b as __pageData,u as default};
